 async importBundle(file){if(!file)return;if(this.working())throw Error('Wait for the active workflow to finish.');if(file.size>20*1024*1024)throw Error('Model bundles must be under 20 MB.');let data;try{data=JSON.parse(await file.text())}catch{throw Error('Select a valid FlowLens model-bundle JSON file.')}if(data.format!=='flowlens-experiment-v1'||!data.experiment)throw Error('This is not a FlowLens model bundle. Use Export model bundle from experiment history.');let x=data.experiment;let model=FlowWorkflow.validateModel(x.model);if(!Array.isArray(x.rows)||!Array.isArray(x.features)||!Array.isArray(x.normalLabels)||!Array.isArray(x.excluded)||typeof x.file!=='string'||!x.result||!Array.isArray(x.result.tests))throw Error('Bundle is missing its dataset or evaluation records.');FlowWorkflow.inspect(x.rows,x.label,x.features,x.normalLabels);if(JSON.stringify(model.schema.map(s=>s.name))!==JSON.stringify(x.result.schema.map(s=>s.name)))throw Error('Model and evaluation feature schemas do not match.');if(x.result.trainCount+x.result.testCount!==x.rows.length||x.result.tests.length!==x.result.testCount)throw Error('Inconsistent train/test record counts.');let normals=new Set(x.normalLabels.map(FlowWorkflow.token)),ids=new Set;let tests=x.result.tests.map(t=>{if(!Number.isInteger(t.id)||t.id<1||t.id>x.rows.length||ids.has(t.id))throw Error('Invalid held-out row identifiers.');ids.add(t.id);let values=x.rows[t.id-1];return{id:t.id,values,actual:normals.has(FlowWorkflow.token(values[x.label]))?'Normal':'Suspicious'}});let rec={id:this.id(),createdAt:this.now(),title:String(x.title||x.file).slice(0,250),file:x.file.slice(0,250),demo:Boolean(x.demo),origin:'Imported model bundle · source unverified',rows:x.rows,label:x.label,features:x.features,normalLabels:x.normalLabels,excluded:x.excluded,model,result:{...x.result,tests,schema:model.schema},job:{state:'complete',stage:'save',startedAt:this.now(),finishedAt:this.now(),stages:[]},saved:false};await this.restoreRecord(rec,true)},
 exportModel(id){let rec=this.experiments.find(x=>x.id===id)||(this.current?.id===id?this.current:null);if(!rec)throw Error('Train or restore a model first.');download('flowlens-model-'+rec.id.slice(0,8)+'.json',JSON.stringify({format:'flowlens-experiment-v1',exportedAt:this.now(),experiment:rec}),'application/json')},
